export function enrichChapter(chapter: Chapter): Chapter {
  const expansion = courseExpansions[chapter.id];
  if (!expansion) return chapter;
  const { extraExercises, ...guide } = expansion;
  // Keep original exercise indices: existing local progress and backups remain valid.
  return { ...chapter, guide, exercises: [...chapter.exercises, ...extraExercises] };
}
